    public static class ArthurSchopenhauer
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Ein neuer Gedanke wird zuerst verlacht, dann bekämpft, bis er nach längerer Zeit als selbstverständlich gilt.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Aber die Sprache um ein Wort ärmer machen heißt das Denken der Nation um einen Begriff ärmer machen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Alle Befreiung, oder was man gemeinhin Glück nennt, ist eigentlich und wesentlich immer nur negativ und durchaus nie positiv.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Alles im Leben giebt kund, daß das irdische Glück bestimmt ist, vereitelt oder als eine Illusion erkannt zu werden.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Alles Urdenken geschieht in Bildern: darum ist die Phantasie ein so nothwendiges Werkzeug desselben, und werden phantasielose Köpfe nie etwas Großes leisten, - es sei denn in der Mathematik.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Aus jeder Seite von David Hume ist mehr zu lernen, als aus Hegels, Herbarts und Schleiermachers sämtlichen philosophischen Werken zusammengenommen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Bei keiner Sache hat man so sehr den Kern von der Schaale zu unterscheiden, wie beim Christentum.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Das Leben, mit seinen stündlichen, täglichen, wöchentlichen und jährlichen, kleinen, größern und großen Widerwärtigkeiten, mit seinen getäuschten Hoffnungen und seinen alle Berechnung vereitelnden Unfällen, trägt so deutlich das Gepräge von etwas, das uns verleidet werden soll, daß es schwer zu begreifen ist, wie man dies hat verkennen können und sich überreden lassen, es sei da, um dankbar genossen zu werden, und der Mensch, um glücklich zu seyn.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Das Talent gleicht dem Schützen, der ein Ziel trifft, welches die Uebrigen nicht erreichen können; das Genie dem, der eines trifft, bis zu welchem sie nicht ein Mal zu sehn vermögen...", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Denn, ich wiederhole es, alle Tugend, die irgendwie eines Lohnes wegen geübt wird, beruht auf klugen, methodischen, weitsehenden Egoismus.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Der heimliche Prosaiker hingegen sucht zum Gedanken den Reim; der Pfusch zum Reim den Gedanken.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Der Lebenslauf des Menschen besteht darin, dass er, von der Hoffnung genarrt, dem Tod in die Arme tanzt.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die Welt ist meine Vorstellung.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die Wahrheit ist keine Hure, die sich Denen an den Hals wirft, welche ihrer nicht begehren: vielmehr ist sie eine so spröde Schöne, daß selbst wer ihr Alles opfert noch nicht ihrer Gunst gewiß seyn darf.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Eine Allegorie ist ein Kunstwerk, welches etwas Anderes bedeutet, als es darstellt.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Eine gefasste Hypothese gibt uns Luchsaugen für alles sie Bestätigende, und macht uns blind für alles ihr Widersprechende.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Er Kant hat aus der Philosophie den Theismus eliminiert, da in ihr, als einer Wissenschaft, und nicht Glaubenslehre, nur Das eine Stelle finden kann, was entweder empirisch gegeben, oder durch haltbare Beweise festgestellt ist.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "In jedem Mikrokosmos liegt der ganze Makrokosmos, und dieser enthält nichts mehr als jener.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Religionen sind dem Volke notwendig, und sind ihm eine unschätzbare Wohltat. Wenn sie jedoch den Fortschritten der Menschheit in der Erkenntnis der Wahrheit sich entgegenstellen wollen; so müssen sie mit möglichster Schonung bei Seite geschoben werden.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Was dem Herzen widerstrebt, läßt der Kopf nicht ein.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Zur Logik verhält sich die Grammatik wie das Kleid zum Leibe.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Zur Philosophie verhält sich die Poesie, wie die Erfahrung sich zur empirischen Wissenschaft verhält.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Ein unpersönlicher Gott ist gar kein Gott, sondern bloß ein missbrauchtes Wort, ein Unbegriff, eine contradictio in adjecto, ein Schiboleth für Philosophieprofessoren, welche, nachdem sie die Sache haben aufgeben müssen, mit dem Worte durchzuschleichen bemüht sind.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Es gibt keine andere Offenbarung als die Gedanken der Weisen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Es gibt nur eine Heilkraft, und das ist die Natur; in Salben und Pillen steckt keine. Höchstens können sie der Heilkraft der Natur einen Wink geben, wo etwas für sie zu tun ist.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Der Arzt sieht den Menschen in seiner ganzen Schwäche, der Advokat in seiner ganzen Schlechtigkeit und der Priester in seiner ganzen Dummheit.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die wohlfeilste Art des Stolzes hingegen ist der Nationalstolz. Denn er verrät in dem damit Behafteten den Mangel an individuellen Eigenschaften, auf die er stolz sein könnte, indem er sonst nicht zu dem greifen würde, was er mit so vielen Millionen teilt.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Was nun andererseits die Menschen gesellig macht ist ihre Unfähigkeit, die Einsamkeit, und in dieser sich selbst, zu ertragen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Dem intellektuell hochstehenden Menschen gewährt nämlich die Einsamkeit einen zweifachen Vortheil: erstlich den, mit sich selber zu seyn, und zweitens den, nicht mit Anderen zu seyn.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Zorn oder Haß in Worten, oder Mienen blicken zu lassen ist unnütz, ist gefährlich, ist unklug, ist lächerlich, ist gemein.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Was aber die Leute gemeiniglich das Schicksal nennen sind meistens nur ihre eigenen dummen Streiche.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Alles wirkliche Dichten und Denken nämlich ist gewissermaaßen ein Versuch, den kleinen Leuten einen großen Kopf aufzusetzen: kein Wunder, daß er nicht gleich gelingt.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Ach, es ist doch ein saures Stück Brod, das Philosophieprofessorenbrod!", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Jede menschliche Vollkommenheit ist einem Fehler verwandt, in welchen überzugehen sie droht; jedoch auch umgekehrt, jeder Fehler, einer Vollkommenheit.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Denn die Moral mittels des Theismus stützen, heißt sie auf Egoismus zurückführen; obgleich die Engländer, wie auch bei uns die untersten Klassen der Gesellschaft, gar nicht die Möglichkeit einer anderen Begründung absehen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Denn bei mir findet, in England, der rothe Rock mehr Glauben, als der schwarze, und Alles, was daselbst zu Gunsten der Kirche, dieser so reichen und bequemen Versorgungsanstalt der mittellosen jüngern Söhne der gesammten Aristokratie, gesagt wird, ist mir eo ipso verdächtig.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Ein eigenthümlicher Fehler der Deutschen ist, daß sie, was vor ihren Füßen liegt, in den Wolken suchen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Wird nämlich das Unrecht von Einer Seite herausgeworfen, so schleicht es sich von der andern wieder herein; weil eben die Unrechtlichkeit tief im menschlichen Wesen liegt.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Aber so ein Gott Jehova, der animi causa und de gaieté de coeur diese Welt der Noth und des Jammers hervorbringt und dann noch gar sich selber Beifall klatscht, mit πάντα καλά λίαν, - Das ist nicht zu ertragen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Alles, was im Christentum Wahres findet, findet sich auch im Brahmanismus und Buddhismus.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Man möchte wahrlich sagen: die Menschen sind die Teufel der Erde, und die Tiere die geplagten Seelen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Der Grundunterschied der Religionen liegt darin, ob sie Optimismus oder Pessimismus sind; keineswegs darin, ob Monotheismus, Polytheismus, Trimurti, Dreieinigkeit, Pantheismus, oder Atheismus (wie der Buddhismus).", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Das Christentum ist eine Allegorie, die einen wahren Gedanken abbildet; aber nicht ist die Allegorie an sich selbst das Wahre.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Entweder glauben oder philosophiren! was man erwählt sei man ganz.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die Fabel von der Pandora ist mir von jeher nicht klar gewesen, ja, ungereimt und verkehrt vorgekommen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Unter den Dichtern unserer Zeit ist Göthe der objektivste, Bryon der subjektivste.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Wie schlecht würde es also um das menschliche Wissen stehn, wenn Schrift und Druck nicht wären! Daher sind die Bibliotheken allein das sichere und bleibende Gedächtnis des menschlichen Geschlechts.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die Barberei kommt wieder, trotz Eisenbahnen, elektrischen Drähten und Luftballons.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Lesen heißt mit einem fremden Kopfe, statt des eigenen, denken.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Wann wir lesen, denkt ein Anderer für uns: wir wiederholen bloß seinen mentalen Proceß. [...] Daher kommt es, daß wer sehr viel und fast den ganzen Tag liest, dazwischen aber sich in gedankenlosem Zeitvertreibe erholt, die Fähigkeit, selbst zu denken, allmälig verliert, - wie Einer der immer reitet, zuletzt das Gehen verlernt.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Unwissenheit degradirt den Menschen erst dann, wann sie in Gesellschaft des Reichthums angetroffen wird.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die Konsonanten sind das Skelett und die Vokale das Fleisch der Wörter.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Hoffnung ist die Verwechselung des Wunsches einer Begebenheit mit ihrer Wahrscheinlichkeit.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Aller Eigensinn beruht darauf, daß der Wille sich an die Stelle der Erkenntniß gedrängt hat.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Es gibt keine Absurdität, die so handgreiflich wäre, daß man sie nicht allen Menschen fest in den Kopf setzen könnte, wenn man nur schon vor ihrem sechsten Jahre, anfienge, sie ihnen einzuprägen, indem man unablässig und mit feierlichstem Ernst sie ihnen vorsagte.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Aber, im Ganzen genommen, liegt, wie längst gesagt ist, die Welt im Argen: die Wilden fressen einander und die Zahmen betrügen einander, und Das nennet man den Lauf der Welt.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Alle Dinge sind herrlich zu SEHN, aber schrecklich zu SEYN.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Das Gehirn denkt, wie der Magen verdaut.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Das Schicksal mischt die Karten, und wir spielen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die Freunde nennen sich aufrichtig; die Feinde sind es: daher man ihren Tadel zur Selbsterkenntnis benutzen sollte, als eine bittre Arznei", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die Erinnerung wirkt wie das Sammlungsglas in der Camera obscura: Sie zieht alles zusammen und bringt dadurch ein viel schöneres Bild hervor, als sein Original ist.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die Gegenwart eines Gedankens ist wie die Gegenwart einer Geliebten.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Durch nichts entziehen wir uns so sehr dem Zwange von außen wie durch Selbstzwang.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Für sein Tun und Lassen kann man keinen anderen zum Muster nehmen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Gerade in Kleinigkeiten, als bei welchen der Mensch sich nicht zusammennimmt, zeigt er seinen Charakter.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Im allgemeinen freilich haben die Weisen aller Zeiten immer dasselbe gesagt, und die Toren, d.h. die unermessliche Majorität aller Zeiten, haben immer dasselbe, nämlich das Gegenteil getan; und so wird es denn auch ferner bleiben.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Ja, es sei herausgesagt: so eng auch Freundschaft, Liebe und Ehe Menschen verbinden; ganz ehrlich meint jeder es am Ende doch nur mit sich selbst und höchstens noch mit seinem Kinde.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Jede Nation spottet über die andere, und alle haben Recht.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Jeder steckt in seinem Bewusstsein wie in seiner Haut und lebt unmittelbar nur in demselben.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Meistens belehrt uns erst der Verlust über den Wert der Dinge.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Vergeben und Vergessen heißt gemachte kostbare Erfahrungen zum Fenster hinauswerfen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Was nun andrerseits die Menschen gesellig macht, ist ihre Unfähigkeit, die Einsamkeit und in dieser sich selbst zu ertragen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Zu unserer Besserung bedürfen wir eines Spiegels.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Zum Leitstern seiner Bestrebungen soll man nicht Bilder der Phantasie nehmen, sondern deutlich gedachte Begriffe.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die Wahrheit kann warten: denn sie hat ein langes Leben vor sich.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Ehrwürdig ist die Wahrheit; nicht was ihr entgegensteht.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Genialität ist Objektivität.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Da ergiebt sich, daß Moral-Predigen leicht, Moral-Begründen schwer ist.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die Willensfreiheit bedeutet, genau betrachtet, eine Existentia ohne Essentia, welches heißt, daß etwas sei und dabei doch nichts sei, welches wiederum heißt, nicht sei also ein Widerspruch ist.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Du kannst thun was du willst: aber du kannst, in jedem gegebenen Augenblick deines Lebens, nur ein Bestimmtes wollen und schlechterdings nicht Anderes, als dieses Eine.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Sind einem gegebenen Menschen, unter gegebenen Umständen, zwei Handlungen möglich, oder nur Eine? - Antwort aller Tiefdenkenden: Nur Eine.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die Ethik ist in Wahrheit die leichteste aller Wissenschaften.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die vermeinte Rechtlosigkeit der Thiere, der Wahn, daß unser Handeln gegen sie ohne moralische Bedeutung sei, oder, wie es in der Sprache jener Moral heißt, daß es gegen Thiere keine Pflichten gebe, ist geradezu eine empörende Rohheit und Barberei des Occidents, deren Quelle im Judenthum liegt.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Mitleid mit den Thieren hängt mit der Güte des Charakters so genau zusammen, daß man zuversichtlich behaupten darf, wer gegen Thiere grausam ist, könne kein guter Mensch seyn.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die Haupt- und Grundtriebfeder im Menschen, wie im Thiere, ist der Egoismus, d. h. der Drang zum Daseyn und Wohlseyn.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Das Leben ist eine mißliche Sache: ich habe mir vorgesetzt, es damit hinzubringen, über dasselbe nachzudenken.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Der leitende Grundsatz der Stilistik sollte sein, dass der Mensch nur einen Gedanken zur Zeit deutlich denken kann; daher ihm nicht zugemutet werden darf, dass er deren mehrere auf einmal denke.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Der Stil ist die Physiognomie des Geistes. Sie ist untrüglicher als die des Leibes. Affektation im Stil ist dem Gesichterschneiden zu vergleichen.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die, welche schwierige, dunkle, verflochtene, zweideutige Reden zusammensetzen, wissen ganz gewiss nicht recht, was sie sagen wollen, sondern haben nur ein dumpfes, nach einem Gedanken erst ringendes Bewusstsein davon.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die Zeichen des Tierkreises sind das Familienwappen der Menschheit.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Ein Denkmal wird die Nachwelt mir errichten.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Jede menschliche Vollkommenheit ist einem Fehler verwandt, in welchen überzugehn sie droht.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Ihre erbärmliche Angst vor meinen Schriften ist Angst vor der Wahrheit.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Wenn man merkt, daß der Gegner überlegen ist und man Unrecht behalten wird, so werde man persönlich, beleidigend, grob.", Author = "Arthur Schopenhauer" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Arthur_Schopenhauer", Text = "Die angeborene Eitelkeit, die besonders hinsichtlich der Verstandeskräfte reizbar ist, will nicht haben, daß was wir zuerst aufgestellt sich als falsch und das des Gegners als Recht ergebe.", Author = "Arthur Schopenhauer" },
        };
    }
}